def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    ID = (0, 0)  # (kind, value): kind 0 = x -> max(x, value), kind 1 = x -> value

    pts = {1, n + 1}
    for op in ops:
        pts.add(op[1])
        pts.add(op[2] + 1)
    pts = sorted(pts)
    idx = {p: i for i, p in enumerate(pts)}
    m = len(pts) - 1  # number of elementary segments

    tag = [ID] * (4 * m)

    def compose(p, c):
        # Apply c first, then p.
        if p[0] == 1:
            return p
        if c[0] == 1:
            return (1, max(c[1], p[1]))
        return (0, max(c[1], p[1]))

    def push(node):
        t = tag[node]
        if t == ID:
            return
        tag[2 * node] = compose(t, tag[2 * node])
        tag[2 * node + 1] = compose(t, tag[2 * node + 1])
        tag[node] = ID

    def update(node, lo, hi, ql, qr, t):
        if qr < lo or hi < ql:
            return
        if ql <= lo and hi <= qr:
            tag[node] = compose(t, tag[node])
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, ql, qr, t)
        update(2 * node + 1, mid + 1, hi, ql, qr, t)

    for op in ops:
        lo = idx[op[1]]
        hi = idx[op[2] + 1] - 1
        if op[0] == 0:
            t = (1, 0)       # erase: becomes blank (0)
        else:
            t = (0, op[3])   # paint: max(current, colour)
        update(1, 0, m - 1, lo, hi, t)

    counts = {}

    def collect(node, lo, hi):
        if lo == hi:
            v = tag[node][1]  # blank start (0) gives the same value for both kinds
            if v > 0:
                length = pts[lo + 1] - pts[lo]
                counts[v] = counts.get(v, 0) + length
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid + 1, hi)

    collect(1, 0, m - 1)
    return [[c, counts[c]] for c in sorted(counts)]
